/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}

/* Tauri Specta mocks */

/** A handler for each generated command, keyed by its `commands` accessor. */
export type MockCommandHandlers = {
    startConvert: (args: { req: ConvertRequest_Deserialize }) => null | Promise<null>,
    cancelConvert: () => boolean | Promise<boolean>,
    settingsGet: () => Settings_Serialize | Promise<Settings_Serialize>,
    settingsSave: (args: { settings: Settings_Deserialize }) => null | Promise<null>,
    pickFolder: (args: { title: string }) => string | null | Promise<string | null>,
    pickPdf: () => string | null | Promise<string | null>,
    inputInfo: (args: { path: string }) => InputInfo_Serialize | Promise<InputInfo_Serialize>,
    mdPreview: (args: { path: string; maxBytes: number | null }) => string | Promise<string>,
    serverCommands: () => ServerCommand[] | Promise<ServerCommand[]>,
    serverLog: (args: { model: string; output: string }) => ServerLog_Serialize | Promise<ServerLog_Serialize>,
    setFolder: (args: { kind: FolderKind; path: string; moveFiles: boolean }) => FolderMove | Promise<FolderMove>,
    openPath: (args: { path: string }) => null | Promise<null>,
    revealPath: (args: { path: string }) => null | Promise<null>,
    openUrl: (args: { url: string }) => null | Promise<null>,
    overview: () => Overview_Serialize | Promise<Overview_Serialize>,
    engineStatus: () => EngineStatus_Serialize | Promise<EngineStatus_Serialize>,
    engineCheck: () => EngineCheck_Serialize | Promise<EngineCheck_Serialize>,
    engineInstall: (args: { tag: string | null }) => null | Promise<null>,
    engineAction: (args: { action: EngineAction; build: string | null }) => null | Promise<null>,
    modelDownload: (args: { id: string }) => null | Promise<null>,
    modelVerify: (args: { id: string }) => ModelFile[] | Promise<ModelFile[]>,
    modelDelete: (args: { id: string }) => null | Promise<null>,
    modelsCheck: () => ModelRevision_Serialize[] | Promise<ModelRevision_Serialize[]>,
    aboutInfo: () => AboutInfo_Serialize | Promise<AboutInfo_Serialize>,
};

/**
 * One command invocation observed by a set of mock handlers.
 *
 * `command` is the `commands` accessor that was called, e.g. `greet`. A command the
 * bindings do not generate has no accessor to record, so it keeps the raw Tauri command
 * name the frontend passed to `invoke` — which is not cased like an accessor. That is why
 * it is `string` rather than a union of accessor names: such a union would be a lie for
 * those calls.
 */
export type MockCall = {
    /**
     * The generated command accessor, e.g. `greet`, or, for a command the bindings don't
     * generate, its raw Tauri command name.
     */
    readonly command: string;
    /**
     * The arguments `invoke` received, not a copy, so it is `unknown`: the generated
     * `commands` accessor passes `{}` for a command with no arguments, and a raw `invoke`
     * can also pass Tauri's array and buffer payload shapes.
     */
    readonly args: unknown;
};

/** The handle `mockCommands` returns for the handlers it installed. */
export type MockCommandsHandle = {
    /**
     * Every call observed since this handle's handlers were installed, oldest first. The
     * array is live, so it keeps growing for as long as those handlers stay installed.
     */
    readonly calls: readonly MockCall[];
    /** Drop the recorded calls. The handlers stay installed. */
    clear(): void;
};

/**
 * Install typed mock handlers for the generated commands.
 *
 * Handlers are installed through `@tauri-apps/api/mocks`'s `mockIPC`, so the application
 * under test keeps importing the real `commands` object and still runs the result transform
 * and channel mapping the bindings wrap around each call.
 *
 * A handler receives the command's arguments and returns its success value; throw (or
 * return a rejected promise) to make the command fail. A command with no handler rejects
 * with an error rather than resolving `undefined`, so a test can't pass by accident.
 *
 * The returned handle records every call these handlers observe, so a test can assert
 * what was invoked:
 *
 * ```ts
 * const calls = mockCommands({ greet: ({ myName }) => `Hello, ${myName}!` });
 * await commands.greet("Brendan");
 * expect(calls.calls).toEqual([{ command: "greet", args: { myName: "Brendan" } }]);
 * ```
 *
 * `calls` is the live history, oldest first, and grows for as long as these handlers stay
 * installed. Each entry holds the `commands` accessor that was called and the arguments
 * `invoke` received — not a copy, and not narrowed to an object, since a raw `invoke` may
 * pass Tauri's array or buffer payload shapes. `clear()` empties it without uninstalling
 * anything. Every call is recorded before it is dispatched, including one that fails
 * because it has no handler or because its handler throws. A command the bindings do not
 * generate is recorded under its raw Tauri command name, since it has no `commands`
 * accessor.
 *
 * Calling `mockCommands` again installs a fresh set of handlers and returns a fresh handle
 * with an empty history; the previous handle keeps its calls but stops growing.
 *
 * Tauri's event mocking is enabled as part of the install (`shouldMockEvents`), so
 * `events` and `tauriEvents` keep working under test without a second installer fighting
 * this one, and the event plugin's internal invokes never reach the record. Note that
 * Tauri's own mock does not implement `emitTo`, which resolves without reaching any
 * listener. Call `clearMocks` from `@tauri-apps/api/mocks` between tests; it uninstalls
 * the handlers but leaves a handle's history alone.
 */
export function mockCommands(handlers: Partial<MockCommandHandlers> = {}): MockCommandsHandle {
    // A copy with no prototype, so a command named after an `Object.prototype` member
    // (`toString`, `constructor`, …) reports that it is unregistered instead of calling
    // whatever the prototype happens to provide.
    const mockHandlers: Partial<MockCommandHandlers> = Object.create(null);
    Object.assign(mockHandlers, handlers);
    const calls: MockCall[] = [];
    __TAURI_MOCK_IPC((cmd, args) => {
        switch (cmd) {
            case "start_convert": calls.push({ command: "startConvert", args }); return mockCommandHandler(mockHandlers.startConvert, "start_convert", args);
            case "cancel_convert": calls.push({ command: "cancelConvert", args }); return mockCommandHandler(mockHandlers.cancelConvert, "cancel_convert", args);
            case "settings_get": calls.push({ command: "settingsGet", args }); return mockCommandHandler(mockHandlers.settingsGet, "settings_get", args);
            case "settings_save": calls.push({ command: "settingsSave", args }); return mockCommandHandler(mockHandlers.settingsSave, "settings_save", args);
            case "pick_folder": calls.push({ command: "pickFolder", args }); return mockCommandHandler(mockHandlers.pickFolder, "pick_folder", args);
            case "pick_pdf": calls.push({ command: "pickPdf", args }); return mockCommandHandler(mockHandlers.pickPdf, "pick_pdf", args);
            case "input_info": calls.push({ command: "inputInfo", args }); return mockCommandHandler(mockHandlers.inputInfo, "input_info", args);
            case "md_preview": calls.push({ command: "mdPreview", args }); return mockCommandHandler(mockHandlers.mdPreview, "md_preview", args);
            case "server_commands": calls.push({ command: "serverCommands", args }); return mockCommandHandler(mockHandlers.serverCommands, "server_commands", args);
            case "server_log": calls.push({ command: "serverLog", args }); return mockCommandHandler(mockHandlers.serverLog, "server_log", args);
            case "set_folder": calls.push({ command: "setFolder", args }); return mockCommandHandler(mockHandlers.setFolder, "set_folder", args);
            case "open_path": calls.push({ command: "openPath", args }); return mockCommandHandler(mockHandlers.openPath, "open_path", args);
            case "reveal_path": calls.push({ command: "revealPath", args }); return mockCommandHandler(mockHandlers.revealPath, "reveal_path", args);
            case "open_url": calls.push({ command: "openUrl", args }); return mockCommandHandler(mockHandlers.openUrl, "open_url", args);
            case "overview": calls.push({ command: "overview", args }); return mockCommandHandler(mockHandlers.overview, "overview", args);
            case "engine_status": calls.push({ command: "engineStatus", args }); return mockCommandHandler(mockHandlers.engineStatus, "engine_status", args);
            case "engine_check": calls.push({ command: "engineCheck", args }); return mockCommandHandler(mockHandlers.engineCheck, "engine_check", args);
            case "engine_install": calls.push({ command: "engineInstall", args }); return mockCommandHandler(mockHandlers.engineInstall, "engine_install", args);
            case "engine_action": calls.push({ command: "engineAction", args }); return mockCommandHandler(mockHandlers.engineAction, "engine_action", args);
            case "model_download": calls.push({ command: "modelDownload", args }); return mockCommandHandler(mockHandlers.modelDownload, "model_download", args);
            case "model_verify": calls.push({ command: "modelVerify", args }); return mockCommandHandler(mockHandlers.modelVerify, "model_verify", args);
            case "model_delete": calls.push({ command: "modelDelete", args }); return mockCommandHandler(mockHandlers.modelDelete, "model_delete", args);
            case "models_check": calls.push({ command: "modelsCheck", args }); return mockCommandHandler(mockHandlers.modelsCheck, "models_check", args);
            case "about_info": calls.push({ command: "aboutInfo", args }); return mockCommandHandler(mockHandlers.aboutInfo, "about_info", args);
            default:
                calls.push({ command: cmd, args });
                throw new Error(`No mock handler registered for command '${cmd}'`);
        }
    }, { shouldMockEvents: true });
    return Object.freeze({
        calls,
        clear: () => {
            calls.length = 0;
        },
    });
}

function mockCommandHandler(handler: ((args: any) => unknown) | undefined, name: string, args: unknown): unknown {
    if (handler === undefined) throw new Error(`No mock handler registered for command '${name}'`);
    return handler(args);
}
